list.definition:
WITH map(
    'hdx_cdn', 'CDN',
    'asn', 'ASN',
    'reqHost', 'Hostname',
    'Edge_GeoInfo', 'Edge pop'
) AS display_name_map
SELECT arrayStringConcat(
    arrayMap(
        x -> if(x = '${next_dim}',
                concat('<span style="display: inline-block; vertical-align: middle; background-color: #3787F3; color: white; padding: 3px 8px; border-radius: 4px;">', display_name_map[x], '</span>'),
                concat('<span style="display: inline-block; vertical-align: middle; background-color: #202226; border: 1px solid #333740; color: #9FA9B8; padding: 3px 8px; border-radius: 4px;">', display_name_map[x], '</span>')
        ),
        ${drill_chain}
    ),
    ' <span style="color:#565a64;">→</span> '
)

